//! Guazzo setup — a per-user installer with no dependencies and no network.
//!
//! Why this exists instead of an MSI/NSIS package: the project builds with
//! MinGW on a machine without the WiX or NSIS toolchains, and the release
//! pipeline already produces a folder of exact bytes. So setup is one small
//! Rust program that carries that folder (`assets/payload.bin`, generated by
//! `scripts/build-setup.mjs`) and writes it to
//! `%LOCALAPPDATA%\Programs\Guazzo`, which needs no elevation and therefore no
//! UAC prompt for an unsigned binary.
//!
//! What it does, in order: asks, writes the files, copies itself in as
//! `uninstall.exe`, adds a Start-menu shortcut, and registers an entry under
//! `HKCU\…\Uninstall` so Apps & Features can remove it. `--uninstall` reverses
//! all four and then deletes itself.
//!
//! `--silent` skips the questions (used by winget and by `build-setup.mjs`
//! verifying an install); `--dir <path>` installs somewhere else (used by the
//! tests so a check never touches a real install).

#![windows_subsystem = "windows"]

use std::env;
use std::ffi::OsStr;
use std::fs;
use std::path::{Path, PathBuf};
use std::process::Command;

const MAGIC: &[u8; 4] = b"GZP1";
const PAYLOAD: &[u8] = include_bytes!("../assets/payload.bin");
const VERSION: &str = match option_env!("GUAZZO_SETUP_VERSION") {
    Some(v) => v,
    None => "0.0.0",
};

#[cfg(windows)]
mod win {
    use std::ffi::c_void;
    #[link(name = "user32")]
    extern "system" {
        fn MessageBoxW(hwnd: *mut c_void, text: *const u16, caption: *const u16, utype: u32) -> i32;
    }
    const MB_YESNO: u32 = 0x0000_0004;
    const MB_OK: u32 = 0x0000_0000;
    const MB_ICONQUESTION: u32 = 0x0000_0020;
    const MB_ICONINFORMATION: u32 = 0x0000_0040;

    fn wide(s: &str) -> Vec<u16> {
        s.encode_utf16().chain(std::iter::once(0)).collect()
    }

    pub fn ask(title: &str, text: &str) -> bool {
        let (t, m) = (wide(text), wide(title));
        // 6 is IDYES
        unsafe { MessageBoxW(std::ptr::null_mut(), t.as_ptr(), m.as_ptr(), MB_YESNO | MB_ICONQUESTION) == 6 }
    }

    pub fn say(title: &str, text: &str) {
        let (t, m) = (wide(text), wide(title));
        unsafe {
            MessageBoxW(std::ptr::null_mut(), t.as_ptr(), m.as_ptr(), MB_OK | MB_ICONINFORMATION);
        }
    }
}

/// Parse the generated payload: `GZP1`, u32 count, then per file
/// `u16 name length, name, u32 byte length, bytes`.
fn files() -> Vec<(String, &'static [u8])> {
    let mut out = Vec::new();
    if PAYLOAD.len() < 8 || &PAYLOAD[0..4] != MAGIC {
        return out;
    }
    let count = u32::from_le_bytes([PAYLOAD[4], PAYLOAD[5], PAYLOAD[6], PAYLOAD[7]]) as usize;
    let mut at = 8usize;
    for _ in 0..count {
        if at + 2 > PAYLOAD.len() {
            break;
        }
        let nlen = u16::from_le_bytes([PAYLOAD[at], PAYLOAD[at + 1]]) as usize;
        at += 2;
        if at + nlen + 4 > PAYLOAD.len() {
            break;
        }
        let name = String::from_utf8_lossy(&PAYLOAD[at..at + nlen]).to_string();
        at += nlen;
        let len = u32::from_le_bytes([PAYLOAD[at], PAYLOAD[at + 1], PAYLOAD[at + 2], PAYLOAD[at + 3]]) as usize;
        at += 4;
        if at + len > PAYLOAD.len() {
            break;
        }
        out.push((name, &PAYLOAD[at..at + len]));
        at += len;
    }
    out
}

fn local_appdata() -> PathBuf {
    env::var_os("LOCALAPPDATA")
        .map(PathBuf::from)
        .unwrap_or_else(|| PathBuf::from("."))
}

fn default_dir() -> PathBuf {
    local_appdata().join("Programs").join("Guazzo")
}

fn shortcut_path() -> Option<PathBuf> {
    env::var_os("APPDATA").map(|a| {
        PathBuf::from(a)
            .join("Microsoft")
            .join("Windows")
            .join("Start Menu")
            .join("Programs")
            .join("Guazzo.lnk")
    })
}

fn ps_quote(s: &Path) -> String {
    // PowerShell single-quoted strings: double the apostrophe.
    s.to_string_lossy().replace('\'', "''")
}

fn make_shortcut(dir: &Path) -> Result<(), String> {
    let Some(lnk) = shortcut_path() else { return Ok(()) };
    let target = dir.join("Guazzo.exe");
    let script = format!(
        "$s=(New-Object -ComObject WScript.Shell).CreateShortcut('{}'); \
         $s.TargetPath='{}'; $s.WorkingDirectory='{}'; $s.IconLocation='{},0'; $s.Save()",
        ps_quote(&lnk),
        ps_quote(&target),
        ps_quote(dir),
        ps_quote(&target)
    );
    let out = Command::new("powershell")
        .args(["-NoProfile", "-ExecutionPolicy", "Bypass", "-Command", &script])
        .output()
        .map_err(|e| format!("could not run PowerShell: {e}"))?;
    if !out.status.success() {
        return Err(String::from_utf8_lossy(&out.stderr).trim().to_string());
    }
    Ok(())
}

fn reg(args: &[&OsStr]) -> bool {
    // Quiet: a machine policy may forbid the write, and a console window
    // flashing an error at somebody who double-clicked Setup is worse than a
    // silent best-effort. The uninstaller tolerates a missing key.
    Command::new("reg")
        .args(args)
        .stdout(std::process::Stdio::null())
        .stderr(std::process::Stdio::null())
        .status()
        .map(|s| s.success())
        .unwrap_or(false)
}

fn register_uninstall(dir: &Path) {
    const KEY: &str = "HKCU\\Software\\Microsoft\\Windows\\CurrentVersion\\Uninstall\\Guazzo";
    let exe = dir.join("Guazzo.exe");
    let uninstall = dir.join("uninstall.exe");
    let uninstall_cmd = format!("\"{}\" --uninstall", uninstall.display());
    let quiet_cmd = format!("\"{}\" --uninstall --silent", uninstall.display());
    let icon = format!("{},0", exe.display());
    let pairs: [(&str, &str); 7] = [
        ("DisplayName", "Guazzo"),
        ("DisplayVersion", VERSION),
        ("Publisher", "Vera"),
        ("InstallLocation", &dir.display().to_string()),
        ("DisplayIcon", &icon),
        ("UninstallString", &uninstall_cmd),
        ("QuietUninstallString", &quiet_cmd),
    ];
    for (name, value) in pairs {
        reg(&[
            OsStr::new("add"),
            OsStr::new(KEY),
            OsStr::new("/v"),
            OsStr::new(name),
            OsStr::new("/t"),
            OsStr::new("REG_SZ"),
            OsStr::new("/d"),
            OsStr::new(value),
            OsStr::new("/f"),
        ]);
    }
    for flag in ["NoModify", "NoRepair"] {
        reg(&[
            OsStr::new("add"),
            OsStr::new(KEY),
            OsStr::new("/v"),
            OsStr::new(flag),
            OsStr::new("/t"),
            OsStr::new("REG_DWORD"),
            OsStr::new("/d"),
            OsStr::new("1"),
            OsStr::new("/f"),
        ]);
    }
}

fn install(dir: &Path, shortcuts: bool) -> Result<Vec<String>, String> {
    let list = files();
    eprintln!("setup: {} payload entries -> {}", list.len(), dir.display());
    if list.is_empty() {
        return Err("the setup payload is missing or damaged".into());
    }
    fs::create_dir_all(dir).map_err(|e| format!("could not create {}: {e}", dir.display()))?;
    for (name, bytes) in &list {
        let path = dir.join(name);
        if let Some(parent) = path.parent() {
            fs::create_dir_all(parent).map_err(|e| format!("could not create {}: {e}", parent.display()))?;
        }
        fs::write(&path, bytes).map_err(|e| {
            format!(
                "could not write {}: {e}\n\nIf Guazzo is running, close it and run Setup again.",
                path.display()
            )
        })?;
    }
    // Copy ourselves in as the uninstaller: one binary, two roles, and no second
    // download for the user to keep track of.
    let me = env::current_exe().map_err(|e| format!("could not locate this program: {e}"))?;
    let uninstaller = dir.join("uninstall.exe");
    if me != uninstaller {
        fs::copy(&me, &uninstaller).map_err(|e| format!("could not write the uninstaller: {e}"))?;
    }
    // A missing shortcut is a warning, not a failed install: the files are in
    // place and Apps & Features knows about them, so the user can still start
    // Guazzo from the install folder and remove it properly.
    let mut warnings = Vec::new();
    if shortcuts {
        if let Err(message) = make_shortcut(dir) {
            warnings.push(format!("The Start-menu shortcut could not be created ({message}). Start Guazzo from\n{}", dir.display()));
        }
    }
    register_uninstall(dir);
    Ok(warnings)
}

fn uninstall(dir: &Path) {
    if let Some(lnk) = shortcut_path() {
        let _ = fs::remove_file(lnk);
    }
    let _ = Command::new("reg")
        .args([
            "delete",
            "HKCU\\Software\\Microsoft\\Windows\\CurrentVersion\\Uninstall\\Guazzo",
            "/f",
        ])
        .stdout(std::process::Stdio::null())
        .stderr(std::process::Stdio::null())
        .status();
    if let Ok(entries) = fs::read_dir(dir) {
        for entry in entries.flatten() {
            let path = entry.path();
            if path.file_name() == Some(OsStr::new("uninstall.exe")) {
                continue;
            }
            if path.is_dir() {
                let _ = fs::remove_dir_all(&path);
            } else {
                let _ = fs::remove_file(&path);
            }
        }
    }
    // The uninstaller is still running and cannot delete itself, so a hidden
    // PowerShell waits for this process to exit and then removes the file and
    // the folder. `ping`/`timeout` were tried first and both are unreliable
    // here: ping needs a network stack and timeout needs a console.
    let me = env::current_exe().unwrap_or_else(|_| dir.join("uninstall.exe"));
    // Only ever delete paths inside the folder being removed. Running setup from
    // a downloads folder with --uninstall must not delete the downloaded file.
    let inside = me.starts_with(dir);
    let script = if inside {
        format!(
            "Start-Sleep -Seconds 2; Remove-Item -LiteralPath '{}' -Recurse -Force -ErrorAction SilentlyContinue",
            ps_quote(dir)
        )
    } else {
        format!(
            "Start-Sleep -Seconds 2; Remove-Item -LiteralPath '{}' -Force -ErrorAction SilentlyContinue; Remove-Item -LiteralPath '{}' -Recurse -Force -ErrorAction SilentlyContinue",
            ps_quote(&me),
            ps_quote(dir)
        )
    };
    let _ = Command::new("powershell")
        .args(["-NoProfile", "-WindowStyle", "Hidden", "-Command", &script])
        .stdout(std::process::Stdio::null())
        .stderr(std::process::Stdio::null())
        .spawn();
}

fn main() {
    let args: Vec<String> = env::args().skip(1).collect();
    let silent = args.iter().any(|a| a == "--silent" || a == "/S" || a == "/s");
    let do_uninstall = args.iter().any(|a| a == "--uninstall");
    let shortcuts = !args.iter().any(|a| a == "--no-shortcut");
    let mut dir = default_dir();
    if let Some(pos) = args.iter().position(|a| a == "--dir") {
        if let Some(value) = args.get(pos + 1) {
            dir = PathBuf::from(value);
        }
    }

    if do_uninstall {
        // Without --dir the folder to remove is the one this file is running
        // from, not the default install path: a user who chose a different
        // folder would otherwise leave the installation behind and delete a
        // folder that is not theirs.
        if !args.iter().any(|a| a == "--dir") {
            if let Some(parent) = env::current_exe().ok().and_then(|p| p.parent().map(Path::to_path_buf)) {
                dir = parent;
            }
        }
        if !silent && !win::ask("Remove Guazzo?", &format!("Remove Guazzo from\n{}?", dir.display())) {
            return;
        }
        uninstall(&dir);
        if !silent {
            win::say("Guazzo", "Guazzo has been removed. Your documents are untouched.");
        }
        return;
    }

    if !silent
        && !win::ask(
            &format!("Install Guazzo {VERSION}?"),
            &format!(
                "Guazzo will be installed to\n{}\n\nIt runs from there without installing anything system-wide, and appears in your Start menu.",
                dir.display()
            ),
        )
    {
        return;
    }

    match install(&dir, shortcuts) {
        Ok(warnings) => {
            if !silent {
                let mut text = format!("Guazzo {VERSION} is installed in\n{}\n\nTo remove it later, use Settings ▸ Apps.", dir.display());
                for warning in &warnings {
                    text.push_str("\n\n");
                    text.push_str(warning);
                }
                win::say("Guazzo is installed", &text);
            }
        }
        Err(message) => {
            eprintln!("setup: {message}");
            if !silent {
                win::say("Guazzo could not be installed", &message);
            }
        }
    }
}
